"""Plain-text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed
from datetime import date

def _own_marks(
    student: Student, marks: Iterable[Mark]
) -> List[Mark]:
    own_marks = list(marks)
    student_ids = {mark.student_id for mark in own_marks}
    if student_ids - {student.student_id}:
        raise ProjectError("mark for a different student")
    return own_marks

def _notice_text(
    student: Student, missed: List[date]
) -> str:
    dates = ", ".join(map(str, missed))
    days = "day" if len(missed) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(missed)} {days}: {dates}."

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice naming the student and each day missed."""
    missed = days_missed(_own_marks(student, marks))
    if not missed:
        raise ProjectError("no absences to report")
    return _notice_text(student, missed)
